src='''from collections import Counter, defaultdict

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Recover the period and color cycle from the visible patterned area.
    best = None
    for period in range(2, 13):
        counts = defaultdict(Counter)
        for r in range(3, h):
            for c in range(3, w):
                value = grid[r][c]
                if value:
                    counts[(r + c) % period][value] += 1
        total = sum(sum(bucket.values()) for bucket in counts.values())
        score = sum(max(bucket.values()) for bucket in counts.values()) / total
        candidate = (score, -period, period, counts)
        if best is None or candidate[:2] > best[:2]:
            best = candidate
    period, counts = best[2], best[3]
    colors = {phase: bucket.most_common(1)[0][0] for phase, bucket in counts.items()}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or (r == 2 and c < 2) or (r >= 3 and c < 2):
                out[r][c] = 1
            elif r == 2 or (r >= 3 and c == 2):
                out[r][c] = 4
            else:
                out[r][c] = colors[(r + c) % period]
    return out
'''
